const j=$input.first().json;
if(!j.script||!j.avatar_provider) throw new Error('script and source avatar provider/skill are required');
const stages=['skill_activated','avatar_render','animation_overlay','captions','export'];
return [{json:{job_id:String(j.job_id||'avatar-'+Date.now()),script:j.script,provider:j.avatar_provider,stages:stages.map((name,index)=>({name,order:index+1,status:index===0?'manual_handoff':'blocked_until_previous'})),output_status:'not_rendered',source_note:'source reports an initial blank render before adding animation/captions'}}];
